[{"order":1,"type":"heading","text":"Next.js: Server-Side Rendering Framework"},{"order":2,"type":"paragraph","text":"Next.js is a popular React framework that enables features like server-side rendering (SSR) and static site generation (SSG). It provides an excellent developer experience with features like automatic code splitting, routing, and API routes. This tutorial will guide you through the fundamentals of Next.js and how to leverage its server-side rendering capabilities."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Basic understanding of React.js"},{"order":5,"type":"bullet_point","text":"Node.js and npm (or yarn) installed on your machine"},{"order":6,"type":"subheading","text":"Setting up a Next.js Project"},{"order":7,"type":"paragraph","text":"Create a new Next.js project using the following command:"},{"order":8,"type":"code","text":"npx create-next-app my-nextjs-app
cd my-nextjs-app"},{"order":9,"type":"paragraph","text":"This command bootstraps a new Next.js project named 'my-nextjs-app'. Navigate into the project directory."},{"order":10,"type":"subheading","text":"Understanding the Project Structure"},{"order":11,"type":"bullet_point","text":"`pages`: This directory contains your application's pages. Each file in this directory becomes a route based on its filename."},{"order":12,"type":"bullet_point","text":"`public`: This directory is for static assets like images, fonts, and other files that you want to serve directly."},{"order":13,"type":"bullet_point","text":"`styles`: This directory contains global CSS files and CSS modules."},{"order":14,"type":"subheading","text":"Creating a Simple Page"},{"order":15,"type":"paragraph","text":"Inside the `pages` directory, create a file named `about.js` with the following content:"},{"order":16,"type":"code","text":"function AboutPage() {
  return (
    <div>
      <h1>About Us</h1>
      <p>This is the about page.</p>
    </div>
  );
}

export default AboutPage;"},{"order":17,"type":"paragraph","text":"This creates a new route at `/about`."},{"order":18,"type":"subheading","text":"Server-Side Rendering (SSR)"},{"order":19,"type":"paragraph","text":"Next.js provides a function called `getServerSideProps` that allows you to fetch data on the server before rendering the page. This is useful for fetching data from an API or database."},{"order":20,"type":"paragraph","text":"Modify `pages/index.js` to fetch data server-side:"},{"order":21,"type":"code","text":"function HomePage({ data }) {
  return (
    <div>
      <h1>Welcome to Next.js!</h1>
      <p>Data from server: {data}</p>
    </div>
  );
}

export async function getServerSideProps(context) {
  // Simulate fetching data from an API
  const data = await new Promise((resolve) => {
    setTimeout(() => {
      resolve('Hello from the server!');
    }, 1000);
  });

  return {
    props: { data }, // will be passed to the page component as props
  };
}

export default HomePage;"},{"order":22,"type":"paragraph","text":"In this example, `getServerSideProps` fetches data and passes it as props to the `HomePage` component. This data is fetched on each request to the page."},{"order":23,"type":"subheading","text":"Static Site Generation (SSG)"},{"order":24,"type":"paragraph","text":"For pages that don't require frequently updated data, you can use Static Site Generation (SSG) with `getStaticProps`. This generates the page at build time, resulting in faster performance."},{"order":25,"type":"paragraph","text":"Create a new file `pages/static.js`:"},{"order":26,"type":"code","text":"function StaticPage({ data }) {
  return (
    <div>
      <h1>Static Page</h1>
      <p>Data: {data}</p>
    </div>
  );
}

export async function getStaticProps(context) {
  const data = 'This data is generated at build time.';

  return {
    props: { data }, // will be passed to the page component as props
  };
}

export default StaticPage;"},{"order":27,"type":"paragraph","text":"`getStaticProps` runs at build time and passes the data as props to the `StaticPage` component."},{"order":28,"type":"subheading","text":"Dynamic Routes"},{"order":29,"type":"paragraph","text":"Next.js supports dynamic routes using square brackets in the `pages` directory. For example, `pages/posts/[id].js` creates a dynamic route for posts with different IDs."},{"order":30,"type":"paragraph","text":"Create a file `pages/posts/[id].js`:"},{"order":31,"type":"code","text":"import { useRouter } from 'next/router';

function Post() {
  const router = useRouter();
  const { id } = router.query;

  return (
    <div>
      <h1>Post ID: {id}</h1>
    </div>
  );
}

export default Post;"},{"order":32,"type":"paragraph","text":"Use `useRouter` hook to access the route parameters. Access the `id` from the `router.query` object."},{"order":33,"type":"subheading","text":"API Routes"},{"order":34,"type":"paragraph","text":"Next.js allows you to create API endpoints by placing files in the `pages/api` directory. These files should export a default function that handles the request and response."},{"order":35,"type":"paragraph","text":"Create a file `pages/api/hello.js`:"},{"order":36,"type":"code","text":"export default function handler(req, res) {
  res.status(200).json({ text: 'Hello' });
}"},{"order":37,"type":"paragraph","text":"This creates an API endpoint at `/api/hello` that returns a JSON response."},{"order":38,"type":"subheading","text":"Conclusion"},{"order":39,"type":"paragraph","text":"Next.js simplifies building React applications with server-side rendering, static site generation, and API routes. This tutorial covered the basics of setting up a Next.js project and implementing SSR, SSG, dynamic routes, and API routes. Explore the Next.js documentation for more advanced features and customization options."}]
